import json, subprocess, sys

def api(endpoint, **params):
    data = {"token": "***"}
    data.update({k: (str(v) if isinstance(v, bool) else v) for k, v in params.items()})
    args = ["curl", "-s", "-X", "POST", f"https://slack.com/api/{endpoint}"]
    for k, v in data.items():
        args += ["-d", f"{k}={v}"]
    out = subprocess.run(args, capture_output=True, text=True).stdout
    d = json.loads(out)
    if not d.get("ok"):
        print("ERR", endpoint, d, file=sys.stderr)
        sys.exit(1)
    return d

channels = []
cursor = None
while True:
    d = api("users.conversations", user="U_VICTOR", exclude_archived="false",
            types="public_channel,private_channel", limit=1000, **({"cursor": cursor} if cursor else {}))
    channels.extend(d["channels"])
    cursor = d.get("response_metadata", {}).get("next_cursor")
    if not cursor:
        break

print(f"victor's channels: {len(channels)}")
for c in channels:
    print(json.dumps({
        "id": c["id"], "name": c.get("name"), "private": c.get("is_private"),
        "created": c.get("created"), "num_members": c.get("num_members"),
        "archived": c.get("is_archived"),
    }))

